    @GetMapping("/unidades/{unidadeId}/servicos")
    public List<ServicoResponse> listar(
            @PathVariable Long unidadeId,
            @RequestParam(name = "somenteDisponiveis", defaultValue = "false") boolean somenteDisponiveis) {
